# regal ignore:directory-package-mismatch
package armo_builtins

import rego.v1

# Deny SandboxTemplate when runtimeClassName is missing or empty.
deny contains msga if {
	allowed := object.get(data.postureControlInputs, "hardenedSandboxRuntimeClasses", [])
	count(allowed) > 0
	template := input[_]
	template.kind in {"Sandbox", "SandboxTemplate"}

	runtime_class := object.get(template, ["spec", "podTemplate", "spec", "runtimeClassName"], "")

	runtime_class == ""

	msga := {
		"alertMessage": sprintf("%s '%v' does not define runtimeClassName.", [template.kind, template.metadata.name]),
		"packagename": "armo_builtins",
		"alertScore": 7,
		"failedPaths": ["spec.podTemplate.spec.runtimeClassName"],
		"reviewPaths": runtime_class_review_paths(template),
		"fixPaths": [],
		"alertObject": {"k8sApiObjects": [template]},
	}
}

# Deny SandboxTemplate when runtimeClassName is not in the approved list.
deny contains msga if {
	allowed := object.get(data.postureControlInputs, "hardenedSandboxRuntimeClasses", [])
	count(allowed) > 0
	template := input[_]
	template.kind in {"Sandbox", "SandboxTemplate"}

	runtime_class := object.get(template, ["spec", "podTemplate", "spec", "runtimeClassName"], "")

	runtime_class != ""
	not runtime_class in allowed

	msga := {
		"alertMessage": sprintf("%s '%v' uses runtimeClassName '%v', which is not in the approved hardened runtime list.", [template.kind, template.metadata.name, runtime_class]),
		"packagename": "armo_builtins",
		"alertScore": 7,
		"failedPaths": ["spec.podTemplate.spec.runtimeClassName"],
		"reviewPaths": ["spec.podTemplate.spec.runtimeClassName"],
		"fixPaths": [],
		"alertObject": {"k8sApiObjects": [template]},
	}
}

# runtimeClassName when it is set, even to "", otherwise its deepest parent
# that exists, so the evidence points at a field that is there.
runtime_class_review_paths(template) := ["spec.podTemplate.spec.runtimeClassName"] if {
	_ = template.spec.podTemplate.spec.runtimeClassName
} else := ["spec.podTemplate.spec"] if {
	is_object(template.spec.podTemplate.spec)
} else := ["spec.podTemplate"] if {
	is_object(template.spec.podTemplate)
} else := ["spec"] if {
	is_object(template.spec)
} else := []

# regal ignore:directory-package-mismatch
package armo_builtins

import rego.v1

# A directly created Sandbox does not pass through the SandboxTemplate secure
# default, so it must disable token automount explicitly.
deny contains msga if {
	sandbox := input[_]
	sandbox.kind == "Sandbox"

	automount := object.get(sandbox, ["spec", "podTemplate", "spec", "automountServiceAccountToken"], null)
	automount != false

	msga := {
		"alertMessage": sprintf("Sandbox '%v' must set automountServiceAccountToken to false; direct Sandbox resources do not receive the SandboxTemplate secure default.", [resource_name(sandbox)]),
		"packagename": "armo_builtins",
		"alertScore": 7,
		"failedPaths": ["spec.podTemplate.spec.automountServiceAccountToken"],
		"reviewPaths": automount_review_paths(sandbox),
		"fixPaths": automount_fix_paths(sandbox),
		"alertObject": {"k8sApiObjects": [sandbox]},
	}
}

# SandboxTemplate processing defaults an omitted value to false. Only an
# explicit true opts out of that protection and should fail posture checks.
deny contains msga if {
	template := input[_]
	template.kind == "SandboxTemplate"

	automount := object.get(template, ["spec", "podTemplate", "spec", "automountServiceAccountToken"], false)
	automount == true

	msga := {
		"alertMessage": sprintf("SandboxTemplate '%v' explicitly enables service account token automounting; omit the field or set it to false.", [resource_name(template)]),
		"packagename": "armo_builtins",
		"alertScore": 7,
		"failedPaths": ["spec.podTemplate.spec.automountServiceAccountToken"],
		"reviewPaths": ["spec.podTemplate.spec.automountServiceAccountToken"],
		"fixPaths": [],
		"alertObject": {"k8sApiObjects": [template]},
	}
}

resource_name(resource) := object.get(resource, ["metadata", "name"], "<unnamed>")

# The field when the Sandbox sets it, otherwise its deepest parent that exists,
# so the evidence points at a field that is there.
automount_review_paths(sandbox) := ["spec.podTemplate.spec.automountServiceAccountToken"] if {
	_ = sandbox.spec.podTemplate.spec.automountServiceAccountToken
} else := ["spec.podTemplate.spec"] if {
	is_object(sandbox.spec.podTemplate.spec)
} else := ["spec.podTemplate"] if {
	is_object(sandbox.spec.podTemplate)
} else := ["spec"] if {
	is_object(sandbox.spec)
} else := []

# An omitted field is added as false. One that is set is left to the reviewer.
automount_fix_paths(sandbox) := [] if {
	_ = sandbox.spec.podTemplate.spec.automountServiceAccountToken
} else := [{"path": "spec.podTemplate.spec.automountServiceAccountToken", "value": "false"}]

# regal ignore:directory-package-mismatch
package armo_builtins

import rego.v1

deny contains msg if {
	wl := input[_]
	wl.kind in {"Sandbox", "SandboxTemplate"}
	pod_spec := object.get(object.get(wl.spec, "podTemplate", {}), "spec", {})
	container_sets := [{"name": "containers", "items": object.get(pod_spec, "containers", [])}, {"name": "initContainers", "items": object.get(pod_spec, "initContainers", [])}]
	container_set := container_sets[_]
	container := container_set.items[i]
	missing := [resource | resource := ["cpu", "memory"][_]; object.get(container, ["resources", "limits", resource], "") == ""]
	count(missing) > 0
	container_path := sprintf("spec.podTemplate.spec.%s[%d]", [container_set.name, i])
	path := sprintf("%s.resources.limits", [container_path])
	fix_paths := [{"path": sprintf("%s.%s", [path, resource]), "value": "YOUR_VALUE"} | resource := missing[_]]
	msg := agent_limit_message(wl, container, missing, path, limits_review_path(container, container_path), fix_paths)
}

agent_limit_message(wl, container, missing, path, review_path, fix_paths) := {"alertMessage": sprintf("Container %q is missing %v limits", [container.name, missing]), "packagename": "armo_builtins", "failedPaths": [path], "reviewPaths": [review_path], "fixPaths": fix_paths, "alertScore": 7, "alertObject": {"k8sApiObjects": [wl]}}

# The deepest of resources.limits, resources and the container itself that the
# container has, so the evidence points at a field that is there.
limits_review_path(container, container_path) := sprintf("%s.resources.limits", [container_path]) if {
	is_object(container.resources.limits)
} else := sprintf("%s.resources", [container_path]) if {
	is_object(container.resources)
} else := container_path

# regal ignore:directory-package-mismatch
package armo_builtins

import rego.v1

deny contains msg if {
	wl := input[_]
	image_ref := agent_digest_image_refs(wl)[_]
	not regex.match(`^.+@sha256:[a-f0-9]{64}$`, image_ref.image)
	msg := agent_digest_message(wl, image_ref.path)
}

agent_digest_image_refs(wl) := [ref | some i; some set in [{"name": "containers", "items": object.get(pod_spec, "containers", [])}, {"name": "initContainers", "items": object.get(pod_spec, "initContainers", [])}]; c := set.items[i]; ref := {"image": c.image, "path": sprintf("spec.podTemplate.spec.%s[%d].image", [set.name, i])}] if {
	wl.kind in {"Sandbox", "SandboxTemplate"}
	pod_spec := object.get(object.get(wl.spec, "podTemplate", {}), "spec", {})
}

agent_digest_image_refs(wl) := [{"image": wl.spec.workerImage, "path": "spec.workerImage"}] if wl.kind == "WorkerPool"

agent_digest_message(wl, path) := {"alertMessage": sprintf("%v image must be pinned to an exact SHA-256 digest", [wl.kind]), "packagename": "armo_builtins", "failedPaths": [path], "reviewPaths": [path], "fixPaths": [], "alertScore": 8, "alertObject": {"k8sApiObjects": [wl]}}

# regal ignore:directory-package-mismatch
package armo_builtins

import rego.v1

deny contains msg if {
	allowed := object.get(data.postureControlInputs, "imageRepositoryAllowList", [])
	count(allowed) > 0
	wl := input[_]
	ref := agent_registry_image_refs(wl)[_]
	not agent_registry_allowed(ref.image, allowed)
	msg := agent_registry_message(wl, ref.path)
}

agent_registry_image_refs(wl) := [ref | some i; some set in [{"name": "containers", "items": object.get(pod_spec, "containers", [])}, {"name": "initContainers", "items": object.get(pod_spec, "initContainers", [])}]; c := set.items[i]; ref := {"image": c.image, "path": sprintf("spec.podTemplate.spec.%s[%d].image", [set.name, i])}] if {
	wl.kind in {"Sandbox", "SandboxTemplate"}
	pod_spec := object.get(object.get(wl.spec, "podTemplate", {}), "spec", {})
}

agent_registry_image_refs(wl) := [{"image": wl.spec.workerImage, "path": "spec.workerImage"}] if wl.kind == "WorkerPool"

agent_registry_allowed(image, allowed) if {
	registry := allowed[_]
	startswith(image, concat("", [registry, "/"]))
}

agent_registry_allowed(image, allowed) if {
	"docker.io" in allowed
	parts := split(image, "/")
	count(parts) > 1
	first := parts[0]
	not contains(first, ".")
	not contains(first, ":")
	first != "localhost"
}

agent_registry_allowed(image, allowed) if {
	"docker.io" in allowed
	count(split(image, "/")) == 1
}

agent_registry_message(wl, path) := {"alertMessage": sprintf("%v image uses a registry outside imageRepositoryAllowList", [wl.kind]), "packagename": "armo_builtins", "failedPaths": [path], "reviewPaths": [path], "fixPaths": [], "alertScore": 8, "alertObject": {"k8sApiObjects": [wl]}}

# regal ignore:directory-package-mismatch
package armo_builtins

import rego.v1

deny contains msg if {
	"strict" in object.get(data.postureControlInputs, "agentSandboxEgressMode", ["managed"])
	wl := input[_]
	wl.kind == "SandboxTemplate"
	not agent_sandbox_has_strict_egress(wl)
	msg := {"alertMessage": "Strict mode requires an explicit managed default-deny egress policy; the managed default still permits public internet", "packagename": "armo_builtins", "failedPaths": ["spec.networkPolicy"], "reviewPaths": strict_egress_review_paths(wl), "fixPaths": strict_egress_fix_paths(wl), "alertScore": 8, "alertObject": {"k8sApiObjects": [wl]}}
}

agent_sandbox_has_strict_egress(wl) if {
	management := object.get(wl, ["spec", "networkPolicyManagement"], null)
	management in {null, "Managed"}
	policy := object.get(wl, ["spec", "networkPolicy"], null)
	is_object(policy)
	egress := object.get(policy, "egress", null)
	is_array(egress)
	count(egress) == 0
}

# spec.networkPolicy when it is there, even as null, otherwise spec, so the
# evidence points at a field that is there.
strict_egress_review_paths(wl) := ["spec.networkPolicy"] if {
	has_network_policy(wl)
} else := ["spec"]

# An omitted policy is added as a managed default-deny one: an empty egress
# list. Only while the policy is managed: an Unmanaged template still fails
# with one, so there is no fix to propose.
strict_egress_fix_paths(wl) := [{"path": "spec.networkPolicy.egress", "value": "[]"}] if {
	not has_network_policy(wl)
	object.get(wl, ["spec", "networkPolicyManagement"], null) in {null, "Managed"}
} else := []

has_network_policy(wl) if {
	_ = wl.spec.networkPolicy
}

# regal ignore:directory-package-mismatch
package armo_builtins

import rego.v1

deny contains msg if {
	maxima := object.get(data.postureControlInputs, "cpu_limit_max", [])
	count(maxima) > 0
	wl := input[_]
	wl.kind == "WorkerPool"
	limit := object.get(wl, ["spec", "template", "resources", "limits", "cpu"], "")
	worker_cpu_limit_invalid(limit, maxima[_])
	msg := worker_ceiling_message(wl, "spec.template.resources.limits.cpu", "CPU")
}

deny contains msg if {
	maxima := object.get(data.postureControlInputs, "memory_limit_max", [])
	count(maxima) > 0
	wl := input[_]
	wl.kind == "WorkerPool"
	limit := object.get(wl, ["spec", "template", "resources", "limits", "memory"], "")
	worker_memory_limit_invalid(limit, maxima[_])
	msg := worker_ceiling_message(wl, "spec.template.resources.limits.memory", "memory")
}

worker_cpu_limit_invalid("", _)

worker_cpu_limit_invalid(limit, maximum) if {
	limit != ""
	worker_cpu_millicores(limit) > worker_cpu_millicores(maximum)
}

worker_memory_limit_invalid("", _)

worker_memory_limit_invalid(limit, maximum) if {
	limit != ""
	worker_memory_bytes(limit) > worker_memory_bytes(maximum)
}

worker_ceiling_message(wl, path, resource) := {"alertMessage": sprintf("Worker Pod %s limit is missing or exceeds the configured ceiling", [resource]), "packagename": "armo_builtins", "failedPaths": [path], "reviewPaths": [path], "fixPaths": [], "alertScore": 7, "alertObject": {"k8sApiObjects": [wl]}}

worker_cpu_millicores(q) := n if {
	s := sprintf("%v", [q])
	endswith(s, "n")
	n := to_number(trim_suffix(s, "n")) / 1000000
} else := n if {
	s := sprintf("%v", [q])
	endswith(s, "u")
	n := to_number(trim_suffix(s, "u")) / 1000
} else := n if {
	s := sprintf("%v", [q])
	endswith(s, "m")
	n := to_number(trim_suffix(s, "m"))
} else := n if {
	s := sprintf("%v", [q])
	endswith(s, "k")
	n := to_number(trim_suffix(s, "k")) * 1000000
} else := n if {
	s := sprintf("%v", [q])
	endswith(s, "M")
	n := to_number(trim_suffix(s, "M")) * 1000000000
} else := n if {
	s := sprintf("%v", [q])
	endswith(s, "G")
	n := to_number(trim_suffix(s, "G")) * 1000000000000
} else := n if {
	s := sprintf("%v", [q])
	endswith(s, "T")
	n := to_number(trim_suffix(s, "T")) * 1000000000000000
} else := n if {
	s := sprintf("%v", [q])
	endswith(s, "P")
	n := to_number(trim_suffix(s, "P")) * 1000000000000000000
} else := n if {
	s := sprintf("%v", [q])
	endswith(s, "E")
	n := to_number(trim_suffix(s, "E")) * 1000000000000000000000
} else := n if {
	n := to_number(q) * 1000
